(()=>{
 const names={en:'English',de:'Deutsch',fr:'Français',es:'Español',it:'Italiano',pt:'Português',nl:'Nederlands',pl:'Polski',sv:'Svenska',zh:'中文'};
 Object.assign(names,{"fi": "Suomi · partial", "da": "Dansk · partial", "nb": "Norsk bokmål · partial", "cs": "Čeština · partial", "sk": "Slovenčina · partial", "hu": "Magyar · partial", "ro": "Română · partial", "el": "Ελληνικά · partial", "tr": "Türkçe · partial", "uk": "Українська · partial", "ar": "العربية · partial", "ja": "日本語 · partial", "ko": "한국어 · partial", "vi": "Tiếng Việt · partial"});
 delete names.sk;delete names.vi;
 const menu=document.querySelector('.language');if(!menu)return;
 menu.innerHTML=Object.entries(names).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');menu.classList.add('notranslate');menu.setAttribute('translate','no');
 let selected='en';try{selected=localStorage.getItem('joyagoo-language')||'en'}catch(e){}if(!names[selected])selected='en';menu.value=selected;
 const navText={en:['Home','Spreadsheet','Guides','How to Buy','FAQ','SEO Updates','Join Joyagoo ↗'],de:['Startseite','Tabelle','Ratgeber','So kaufst du','FAQ','SEO-Neuigkeiten','Joyagoo beitreten ↗'],fr:['Accueil','Tableur','Guides','Comment acheter','FAQ','Actualités SEO','Rejoindre Joyagoo ↗'],es:['Inicio','Hoja de cálculo','Guías','Cómo comprar','Preguntas frecuentes','Novedades SEO','Unirse a Joyagoo ↗'],it:['Home','Foglio prodotti','Guide','Come acquistare','Domande frequenti','Novità SEO','Unisciti a Joyagoo ↗'],pt:['Início','Planilha','Guias','Como comprar','Perguntas frequentes','Atualizações SEO','Entrar no Joyagoo ↗'],nl:['Home','Spreadsheet','Gidsen','Hoe te kopen','Veelgestelde vragen','SEO-updates','Aanmelden bij Joyagoo ↗'],pl:['Start','Arkusz','Poradniki','Jak kupować','FAQ','Aktualizacje SEO','Dołącz do Joyagoo ↗'],sv:['Hem','Kalkylblad','Guider','Så handlar du','Vanliga frågor','SEO-uppdateringar','Gå med i Joyagoo ↗'],zh:['首页','电子表格','指南','如何购买','常见问题','SEO 更新','注册 Joyagoo ↗']};
 Object.assign(navText,{"fi": ["Etusivu", "Tuotetaulukko", "Guides", "Näin ostat", "Usein kysytyt kysymykset", "SEO", "Joyagoo ↗"], "da": ["Forside", "Produktoversigt", "Guides", "Sådan køber du", "Ofte stillede spørgsmål", "SEO", "Joyagoo ↗"], "nb": ["Hjem", "Produktoversikt", "Guides", "Slik kjøper du", "Vanlige spørsmål", "SEO", "Joyagoo ↗"], "cs": ["Domů", "Přehled produktů", "Guides", "Jak nakupovat", "Časté dotazy", "SEO", "Joyagoo ↗"], "sk": ["Domov", "Prehľad produktov", "Guides", "Ako nakupovať", "Časté otázky", "SEO", "Joyagoo ↗"], "hu": ["Kezdőlap", "Terméklista", "Guides", "Hogyan vásárolj", "Gyakori kérdések", "SEO", "Joyagoo ↗"], "ro": ["Acasă", "Lista de produse", "Guides", "Cum cumperi", "Întrebări frecvente", "SEO", "Joyagoo ↗"], "el": ["Αρχική", "Κατάλογος προϊόντων", "Guides", "Πώς να αγοράσετε", "Συχνές ερωτήσεις", "SEO", "Joyagoo ↗"], "tr": ["Ana sayfa", "Ürün listesi", "Guides", "Nasıl satın alınır", "Sıkça sorulan sorular", "SEO", "Joyagoo ↗"], "uk": ["Головна", "Каталог товарів", "Guides", "Як купувати", "Поширені запитання", "SEO", "Joyagoo ↗"], "ar": ["الرئيسية", "قائمة المنتجات", "Guides", "كيفية الشراء", "الأسئلة الشائعة", "SEO", "Joyagoo ↗"], "ja": ["ホーム", "商品一覧", "Guides", "購入方法", "よくある質問", "SEO", "Joyagoo ↗"], "ko": ["홈", "상품 목록", "Guides", "구매 방법", "자주 묻는 질문", "SEO", "Joyagoo ↗"], "vi": ["Trang chủ", "Danh sách sản phẩm", "Guides", "Cách mua hàng", "Câu hỏi thường gặp", "SEO", "Joyagoo ↗"]});
 navText.ru=['Главная','Таблица товаров','Руководства','Как купить','Вопросы и ответы','SEO','Присоединиться к Joyagoo ↗'];
 navText.id=['Beranda','Daftar produk','Panduan','Cara membeli','Tanya jawab','SEO','Gabung Joyagoo ↗'];
 const addedNavLabels={"fi":["Oppaat","Liity Joyagoohon ↗"],"da":["Vejledninger","Tilmeld dig Joyagoo ↗"],"nb":["Veiledninger","Bli med i Joyagoo ↗"],"cs":["Průvodci","Připojit se k Joyagoo ↗"],"sk":["Sprievodcovia","Pripojiť sa k Joyagoo ↗"],"hu":["Útmutatók","Csatlakozás a Joyagoohoz ↗"],"ro":["Ghiduri","Alăturați-vă Joyagoo ↗"],"el":["Οδηγοί","Εγγραφείτε στο Joyagoo ↗"],"tr":["Rehberler","Joyagoo'ya katılın ↗"],"uk":["Посібники","Приєднатися до Joyagoo ↗"],"ar":["الأدلة","انضم إلى Joyagoo ↗"],"ja":["ガイド","Joyagooに参加 ↗"],"ko":["가이드","Joyagoo 가입 ↗"],"vi":["Hướng dẫn","Tham gia Joyagoo ↗"]};
 for(const [language,labels] of Object.entries(addedNavLabels)){ navText[language][2]=labels[0]; navText[language][6]=labels[1]; }
 const seoLabels={en:'SEO Updates',de:'SEO-Neuigkeiten',fr:'Actualités SEO',es:'Novedades SEO',it:'Novità SEO',pt:'Atualizações SEO',nl:'SEO-updates',pl:'Aktualizacje SEO',sv:'SEO-uppdateringar',zh:'SEO 更新',fi:'SEO-päivitykset',da:'SEO-opdateringer',nb:'SEO-oppdateringer',cs:'SEO novinky',hu:'SEO-frissítések',ro:'Actualizări SEO',el:'Ενημερώσεις SEO',tr:'SEO güncellemeleri',uk:'Оновлення SEO',ar:'تحديثات SEO',ja:'SEO更新情報',ko:'SEO 업데이트',ru:'Новости SEO',id:'Pembaruan SEO'};
 function applyNav(){document.documentElement.lang=selected==='zh'?'zh-CN':selected;document.documentElement.dir=selected==='ar'?'rtl':'ltr';let v=navText[selected]||navText.en;document.querySelectorAll('.links a').forEach(el=>{const i={'/':0,'/spreadsheet/':1,'/guides/':2,'/how-to-buy/':3,'/faq/':4,'/seo-updates/':5}[el.getAttribute('href')];if(i!==undefined){el.classList.add('notranslate');el.textContent=i===5?(seoLabels[selected]||seoLabels.en):v[i]}});const reg=document.querySelector('.register');if(reg){reg.classList.add('notranslate');reg.textContent=v[6]}}applyNav();
 menu.addEventListener('change',()=>{selected=names[menu.value]?menu.value:'en';applyNav();try{localStorage.setItem('joyagoo-language',selected)}catch(e){}});
 menu.dispatchEvent(new Event('change'));
})();
